:root { font-family: system-ui, sans-serif; color: #172b42; background: #f5f7fa; }
body { margin: 0; }
main { max-width: 760px; margin: 64px auto; padding: 28px; background: white; border: 1px solid #d8e0e9; border-radius: 12px; }
h1 { margin-top: 0; overflow-wrap: anywhere; }
label { display: block; font-weight: 600; margin-bottom: 8px; }
.create-controls { display: flex; gap: 12px; }
input { min-width: 0; flex: 1; padding: 10px; border: 1px solid #77889a; border-radius: 5px; font: inherit; }
button { background: #164d88; color: white; border: 0; border-radius: 5px; padding: 11px 16px; font: inherit; cursor: pointer; }
button:hover { background: #103a68; }
button:disabled { opacity: .6; cursor: wait; }
